// ❌ 전역에 저장 — window는 루트라 GC 못 건드림
window.cache = fetchBigData()
// 다 쓴 후 반드시
window.cache = null  // 참조 끊기 ✅

// ❌ 이벤트 리스너 미제거 — window에 걸려있어서 누수
useEffect(() => {
  window.addEventListener('resize', handler)
}, [])

// ✅ cleanup으로 참조 끊기
useEffect(() => {
  window.addEventListener('resize', handler)
  return () => window.removeEventListener('resize', handler)
}, [])

